from flask import Flask, jsonify
import sqlite3

app = Flask(__name__)

@app.route('/is_moderator/<username>')
def is_moderator(username):
    # Connect to the database
    conn = sqlite3.connect('users.db')
    cursor = conn.cursor()

    # Execute a query to check if the user is a moderator
    cursor.execute("SELECT is_moderator FROM users WHERE username = ?", (username,))
    result = cursor.fetchone()

    # Close the database connection
    conn.close()

    # Return the result of the query
    if result:
        return jsonify({"username": username, "is_moderator": bool(result[0])})
    else:
        return jsonify({"username": username, "is_moderator": False})

if __name__ == '__main__':
    app.run(host='localhost', port=5000)

